 $nav=[['home','Khám phá việc làm']];
 if ($user) {
    if ($user['role']==='candidate') $nav=[['dashboard','Tổng quan'],['home','Tìm việc'],['recommendations','Gợi ý AI'],['resume','CV của tôi'],['applications','Đơn ứng tuyển'],['saved','Đã lưu'],['profile','Hồ sơ cá nhân']];
    if ($user['role']==='recruiter') $nav=[['dashboard','Tổng quan'],['myjobs','Tin tuyển dụng'],['applicants','Ứng viên'],['profile','Doanh nghiệp'],['home','Khám phá việc làm']];
    if ($user['role']==='admin') $nav=[['dashboard','Tổng quan'],['admin_jobs','Duyệt tin'],['admin_users','Người dùng'],['admin_audit','Nhật ký'],['admin_emails','Email'],['home','Việc làm']];
 }
 $icons=['home'=>'⌕','dashboard'=>'◫','recommendations'=>'✦','resume'=>'▤','applications'=>'▣','saved'=>'♡','profile'=>'◉',
 'myjobs'=>'▦','applicants'=>'♙','admin_jobs'=>'✓','admin_users'=>'♙','admin_audit'=>'≡','admin_emails'=>'✉'];
 $fl=$_SESSION['sr_flash']??null;unset($_SESSION['sr_flash']);
 $roleLabel=$user ? (['candidate'=>'Ứng viên','recruiter'=>'Nhà tuyển dụng','admin'=>'Quản trị viên'][$user['role']]??'Tài khoản') : '';
 ?><!doctype html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101b31"><meta name="description" content="SmartRecruit AI - Nền tảng tuyển dụng với phân tích CV và gợi ý việc làm."><title><?=h($title)?> · SmartRecruit AI</title><link rel="stylesheet" href="assets/style.css?v=4"><link rel="stylesheet" href="assets/v4.css?v=4"><script>try{document.documentElement.dataset.theme=localStorage.getItem('sr_theme')==='dark'?'dark':'light'}catch(e){}</script><script src="assets/app.js?v=4" defer></script></head>
 <body><a class="skip-link" href="#main-content">Chuyển đến nội dung</a><header class="topbar"><div class="topbar-inner"><a class="brand" href="index.php" aria-label="SmartRecruit AI - trang chủ"><span class="brand-mark" aria-hidden="true">S<span class="brand-dot"></span></span><span>smart<span class="accent">recruit</span><small>CAREER INTELLIGENCE</small></span></a><nav class="nav-desktop" aria-label="Menu chính"><a class="<?=($active==='home'?'nav-active':'')?>" href="<?=sr_url('home')?>">Khám phá việc làm</a><?php if($user): ?><a class="<?=($active==='dashboard'?'nav-active':'')?>" href="<?=sr_url('dashboard')?>">Tổng quan</a><?php if($user['role']==='candidate'): ?><a class="<?=($active==='recommendations'?'nav-active':'')?>" href="<?=sr_url('recommendations')?>">✦ Gợi ý AI</a><?php endif;?><a class="notif-link" href="<?=sr_url('notifications')?>" aria-label="Thông báo, <?=$unread?> chưa đọc">◉ <?php if($unread): ?><span class="nav-count"><?=$unread?></span><?php endif;?></a><a class="account-pill" href="<?=sr_url('profile')?>"><span class="avatar small-avatar"><?=h(sr_initials($user['name']))?></span><span><?=h(sr_snip($user['name'],17))?></span></a><form method="post" class="inline"><?=sr_token()?><input type="hidden" name="action" value="logout"><button class="nav-logout" type="submit">Đăng xuất</button></form><?php else: ?><a href="<?=sr_url('login')?>">Đăng nhập</a><a class="button primary sm" href="<?=sr_url('register')?>">Tạo tài khoản <span aria-hidden="true">↗</span></a><?php endif;?></nav><div class="nav-controls"><button class="theme-toggle" type="button" data-theme-toggle aria-label="Đổi chế độ sáng tối" title="Chế độ sáng/tối">◐</button><button class="menu-toggle" type="button" data-menu aria-label="Mở menu" aria-controls="sr-mobile-menu" aria-expanded="false">☰</button></div></div></header>
 <div class="mobile-menu" id="sr-mobile-menu" data-menu-panel><?php foreach($nav as [$p,$label]): ?><a href="<?=sr_url($p)?>"><?=h($label)?></a><?php endforeach;?><?php if($user): ?><a href="<?=sr_url('notifications')?>">Thông báo (<?=$unread?>)</a><form method="post"><?=sr_token()?><input type="hidden" name="action" value="logout"><button>Đăng xuất</button></form><?php else:?><a href="<?=sr_url('login')?>">Đăng nhập</a><a href="<?=sr_url('register')?>">Đăng ký</a><?php endif;?></div>
 <div class="site-body"><div class="site-grid"><?php if ($user && $active!=='home' && $active!=='job' && $active!=='login' && $active!=='register'):?><aside class="sidebar" aria-label="Menu điều hướng"><div class="sidebar-caption">KHÔNG GIAN LÀM VIỆC</div><?php foreach($nav as [$p,$label]): ?><a class="side-link <?=($active===$p?'selected':'')?>" href="<?=sr_url($p)?>" <?=($active===$p?'aria-current="page"':'')?>><span class="side-icon" aria-hidden="true"><?=h($icons[$p]??'◦')?></span><span><?=h($label)?></span><?php if($p==='recommendations'): ?><span class="side-spark">AI</span><?php endif;?></a><?php endforeach;?><div class="sidebar-bottom"><div class="sidebar-help"><span class="sidebar-help-icon" aria-hidden="true">✦</span><strong>SmartRecruit AI</strong><p>Phân tích kỹ năng, khám phá cơ hội nghề nghiệp phù hợp.</p><?php if($user['role']==='candidate'): ?><a href="<?=sr_url('recommendations')?>">Xem gợi ý AI ↗</a><?php elseif($user['role']==='recruiter'): ?><a href="<?=sr_url('job_form')?>">Đăng tin mới ↗</a><?php else: ?><a href="<?=sr_url('admin_jobs')?>">Duyệt tin ↗</a><?php endif;?></div><div class="sidebar-foot"><span class="dot"></span> SmartRecruit · v4.0</div></div></aside><?php endif;?><main id="main-content" class="main <?=(!$user||in_array($active,['home','job','login','register'],true))?'wide':''?>" tabindex="-1">
 <?php if ($fl):?><div class="flash <?=h($fl['type']??'info')?>" role="status"><?=h($fl['message'])?><button type="button" data-dismiss aria-label="Đóng">×</button></div><?php endif;?>
 <?php
}
function sr_layout_end():void {?></main></div></div><footer class="footer"><span>© <?=date('Y')?> SmartRecruit AI · Nền tảng hỗ trợ tuyển dụng</span><span>Điểm AI là tham khảo, quyết định tuyển dụng thuộc về con người.</span></footer></body></html><?php }
function sr_page_heading(string $eyebrow,string $title,string $desc=''):void { ?><div class="page-heading"><div><span class="overline"><?=h($eyebrow)?></span><h1><?=h($title)?></h1><?php if($desc):?><p><?=h($desc)?></p><?php endif;?></div></div><?php }
function sr_job_card(array $j,bool $saved=false):void {
 $name=(string)$j['company'];$type=(string)($j['job_type']??'full_time');$mode=(string)($j['work_mode']??'onsite');
 $user=sr_current();$candidate=$user&&$user['role']==='candidate';
 $rawSkills=sr_skills((string)$j['skills']);
 ?><article class="job-card"><div class="job-header"><span class="company-logo" aria-hidden="true"><?=h(sr_initials($name))?></span><span class="chip soft"><?=h(sr_status($type))?></span></div><div class="muted company-name"><?=h($name)?></div><h3><a href="<?=sr_url('job',['id'=>$j['id']])?>"><?=h($j['title'])?></a></h3><div class="meta"><span>⌖ <?=h($j['location']?:'Toàn quốc')?></span><span>◷ <?=h(sr_status($mode))?></span></div><div class="skills"><?php foreach(array_slice($rawSkills,0,3) as $skill):?><span><?=h($skill)?></span><?php endforeach;?><?php if(count($rawSkills)>3):?><span class="more-skills">+<?=count($rawSkills)-3?></span><?php endif;?></div><div class="job-card-bottom"><span class="salary"><?=h($j['salary']?:'Thỏa thuận')?></span><div class="job-card-cta"><?php if($candidate):?><form method="post" class="inline save-inline"><?=sr_token()?><input type="hidden" name="action" value="save_job"><input type="hidden" name="job_id" value="<?=(int)$j['id']?>"><input type="hidden" name="return_page" value="<?=$saved?'saved':'home'?>"><button class="save-toggle <?=$saved?'is-saved':''?>" type="submit" title="<?=$saved?'Bỏ lưu':'Lưu công việc'?>" aria-label="<?=$saved?'Bỏ lưu':'Lưu công việc'?>"><?=$saved?'♥':'♡'?></button></form><?php endif;?><a class="text-link" href="<?=sr_url('job',['id'=>$j['id']])?>">Chi tiết <span aria-hidden="true">↗</span></a></div></div></article><?php
}
